This PR lets you add types based on your configuration.

```
$ npx bknd types --help
Usage: bknd types [options]

generate types

Options:
  -o, --outfile <outfile>  output file (default: "bknd-types.d.ts")
  --no-write               do not write to file
  -h, --help               display help for command
```

example schema:
```ts
import { em, entity, text, boolean, date, number, json, jsonSchema, enumm } from "bknd/data";

const schema = em(
   {
      todo: entity(
         "todo",
         {
            title: text().required(),
            done: boolean(),
            created_at: date(),
            views: number({
               description: "number of views",
            }),
            status: enumm({ enum: ["one", "two"] }),
            json: json(),
            jsonSchema: jsonSchema({
               schema: {
                  type: "object",
                  properties: { a: { type: "string", minLength: 3 } },
               },
            }),
         },
         {
            description: "A simple todo",
         },
      ),
      users: entity("users", {
         name: text(),
         bio: text(),
         age: number(),
         some: number().required(),
      }, {}, "system"), // simulates system entity
   },
   (ctx, schema) => {
      ctx.relation(schema.todo).manyToOne(schema.users);
   },
);
```

output:
```ts
import type { DB } from "bknd/core";
import type { Insertable, Selectable, Updateable, Generated } from "kysely";
import type { FromSchema } from "json-schema-to-ts";

declare global {
  type BkndEntity<T extends keyof DB> = Selectable<DB[T]>;
  type BkndEntityCreate<T extends keyof DB> = Insertable<DB[T]>;
  type BkndEntityUpdate<T extends keyof DB> = Updateable<DB[T]>;
}

/**
 * A simple todo
 */
export interface Todo {
  id: Generated<number>;
  title: string;
  done?: boolean;
  created_at?: Date | string;
  // number of views
  views?: number;
  status?: "one" | "two";
  json?: any;
  jsonSchema?: FromSchema<{
    type: "object", 
    properties: {
      a: {
        type: "string", 
        minLength: 3
      }
    }
  }>;
  users_id?: number;
  users?: DB["users"];
}

interface Database {
  todo: Todo;
}

declare module "bknd/core" {
  interface Users {
    name?: string;
    bio?: string;
    age?: number;
    some: number;
    todo?: Todo[];
  }

  interface DB extends Database {}
}
```

